fn largest_power_of_two_le(n: i8) -> i8 {
    // Precondition: n >= 1
    let mut z: i8 = 1;
    // Keep doubling z while the next power of two (2*z) is <= n.
    // Checking z <= n/2 ensures 2*z <= n without overflow.
    while z <= n / 2 {
        z *= 2;
    }
    z
}

fn solve(n: i8) -> i8 {
    // Precondition: n >= 1
    if n % 2 != 0 {
        // If n is odd, result = (n - 1) / 2
        (n - 1) / 2
    } else {
        // If n is even, find the largest power of two z <= n,
        // then result = (n - z) / 2
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

